pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(address(this), 1 ether);
        (bool s,) = address(c).call{value: 1 ether}(abi.encodeWithSignature("sendTo(address,uint256)", address(this), uint256(0)));
        FundSender fs = new FundSender{value: 1 ether}();
        fs.sendTo(address(c));

        uint256 balBefore = address(c).balance;

        vm.deal(caller, amount);

        bool ok;
        vm.prank(caller);
        try c.sendTo(caller, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        assertTrue(!ok || caller == address(this));
    }
}

contract FundSender {
    constructor() payable {}
    function sendTo(address target) public {
        selfdestruct(payable(target));
    }
}
